WITH parsed AS (SELECT id, host, log_ts, level, latency_ms, status_code, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, SIZE(context) AS num_context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['trace'] AS trace, COALESCE(context['trace'], 'direct') AS trace_or_default FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, CASE WHEN num_context >= 87 THEN 'LARGE' ELSE 'SMALL' END AS num_context_tier, PERCENTILE_APPROX(retry_count, 0.9) AS retry_count_p90, STDDEV_SAMP(latency_ms) AS latency_ms_stddev, MIN(log_ts) AS first_log_ts FROM parsed GROUP BY hour_window, num_context_tier ORDER BY num_context_tier DESC NULLS LAST;
